import subprocess

# Example of running a command with subprocess
def compile_code(file_path, language):
    try:
        if language == 'typescript':
            result = subprocess.run(['tsc', file_path], capture_output=True, text=True)
        elif language == 'cpp':
            result = subprocess.run(['g++', file_path, '-o', 'output'], capture_output=True, text=True)

        if result.returncode != 0:
            print("Compilation Error:", result.stderr)
        else:
            print("Compilation Successful")
    except Exception as e:
        print("Error:", str(e))

